"""Build project-demo.mp4 from LIVE runs of project/main.py (nothing is typed in by hand).

Every terminal scene runs the real command at build time and shows exactly what it printed.
Slides show figures generated by the benchmark. Output: 1280x720, H.264 + AAC (silent track),
captions on screen instead of a voice-over.

    python docs/build/make_demo_video.py            # writes project-demo.mp4 at the repo root
"""
from __future__ import annotations

import json
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

from PIL import Image, ImageDraw, ImageFont

ROOT = Path(__file__).resolve().parents[2]
W, H = 1280, 720
BG, INK, MUTED, ACCENT = (16, 22, 34), (236, 239, 244), (150, 160, 178), (95, 160, 240)
TERM_BG, GREEN, RED, AMBER = (12, 14, 18), (120, 210, 140), (240, 120, 110), (235, 190, 90)
SANS = "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf"
SANS_B = "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf"
MONO = "/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf"
f = lambda path, size: ImageFont.truetype(path, size)

frames: list[tuple[Image.Image, float]] = []


def run(args: list[str]) -> str:
    out = subprocess.run([sys.executable, str(ROOT / "project" / "main.py"), *args], cwd=ROOT,
                         capture_output=True, text=True, timeout=600)
    return out.stdout


def slide(title: str, lines: list[str], secs: float, image: Path | None = None, kicker: str = "") -> None:
    im = Image.new("RGB", (W, H), BG)
    d = ImageDraw.Draw(im)
    if kicker:
        d.text((70, 48), kicker.upper(), font=f(SANS_B, 18), fill=ACCENT)
    d.text((70, 76), title, font=f(SANS_B, 40), fill=INK)
    y = 150
    if image:
        pic = Image.open(image).convert("RGB")
        pic.thumbnail((W - 140, 400))
        im.paste(pic, ((W - pic.width) // 2, y))
        y += pic.height + 24
    for line in lines:
        size, color = (24, INK) if not line.startswith("~") else (20, MUTED)
        d.text((70, y), line.lstrip("~"), font=f(SANS, size), fill=color)
        y += size + 14
    d.text((70, H - 40), "Rakshaka AI · Byte Benders, University of Moratuwa · early demo, 20 Nov 2026",
           font=f(SANS, 15), fill=MUTED)
    frames.append((im, secs))


def wrap(line: str, width: int = 118) -> list[str]:
    if len(line) <= width:
        return [line]
    out, cur, indent = [], "", " " * (len(line) - len(line.lstrip()))
    for word in line.split(" "):
        if len(cur) + len(word) + 1 > width:
            out.append(cur)
            cur = indent + "  " + word
        else:
            cur = (cur + " " + word) if cur else word
    return out + [cur]


def colour(line: str):
    if line.startswith("Verdict"):
        return RED if "SCAM" in line else AMBER if "UNCERTAIN" in line else GREEN
    if "skipped" in line:
        return MUTED
    return INK


def terminal(caption: str, command: str, output: str, hold: float, note: str = "") -> None:
    lines = [l for raw in output.rstrip().splitlines() for l in wrap(raw)]
    font = f(MONO, 15)

    def draw(typed: str, shown: int, cursor: bool) -> Image.Image:
        im = Image.new("RGB", (W, H), BG)
        d = ImageDraw.Draw(im)
        d.text((40, 22), caption, font=f(SANS_B, 24), fill=INK)
        d.rounded_rectangle((30, 64, W - 30, H - 50), radius=10, fill=TERM_BG)
        for i, c in enumerate([(255, 95, 86), (255, 189, 46), (39, 201, 63)]):
            d.ellipse((48 + i * 20, 76, 60 + i * 20, 88), fill=c)
        y = 104
        d.text((48, y), "$ " + typed + ("▌" if cursor else ""), font=font, fill=GREEN)
        y += 26
        for line in lines[:shown]:
            d.text((48, y), line, font=font, fill=colour(line))
            y += 19
        if note and shown == len(lines):
            d.text((40, H - 40), note, font=f(SANS, 16), fill=AMBER)
        return im

    for k in range(1, 5):
        frames.append((draw(command[: len(command) * k // 4], 0, True), 0.35))
    frames.append((draw(command, 0, False), 0.6))
    step = max(1, len(lines) // 4)
    for n in range(step, len(lines), step):
        frames.append((draw(command, n, False), 0.5))
    frames.append((draw(command, len(lines), False), hold))


def main() -> Path:
    runtime = ROOT / "project" / "runtime"
    shutil.rmtree(runtime, ignore_errors=True)        # clean review queue for the demo
    run(["train"])

    slide("Rakshaka AI", ["A multi-agent second opinion on scam messages",
                          "in Sinhala, Tamil, English, Singlish and Tanglish", "",
                          "~Team Byte Benders · University of Moratuwa · Innodata AI Catalyst 2026, University Track",
                          "~EARLY DEMO (20 Nov). The full demo comes with the MVP on 29 Nov.",
                          "~No voice-over: every terminal scene is a live run of project/main.py, shown as printed."],
          8, kicker="Cybersecurity")
    slide("The problem", ["Scam SMS and WhatsApp messages arrive in the user's own language,",
                          "look official, and push for action within minutes.", "",
                          "• No content checker we found supports Sinhala or Tamil",
                          "• Tactics change every month (fake post office, digital ID, GovPay fines…)",
                          "• One signal is not enough: wording, link, sender and tactic each catch a different part",
                          "", "~Who it is for: anyone with a phone, especially older adults and first-time digital-bank users"],
          16, kicker="Why")
    slide("Nine agents on a shared blackboard", ["~Specialists run in parallel with timeouts, retries and fallbacks. The arbiter resolves",
                                                 "~conflicts with explicit rules; unsure messages go to a human. Every post is traced."],
          16, image=ROOT / "docs" / "figures" / "architecture.png", kicker="Architecture")

    demos = [
        ("1 · Fake post-office fee: look-alike link and sender",
         ["check", "SLKPOST: Your parcel could not be delivered due to unpaid customs fee of Rs 92. Pay at slpost-lk.top/pay within 24 hours.", "--sender", "SLKPOST"],
         'check "SLKPOST: ... unpaid customs fee of Rs 92. Pay at slpost-lk.top/pay ..." --sender SLKPOST', ""),
        ("2 · A real bank OTP message: the safety advice is recognised",
         ["check", "Your BOC OTP is 482913. Never share this OTP with anyone. BOC staff will never ask for it.", "--sender", "BOC"],
         'check "Your BOC OTP is 482913. Never share this OTP with anyone. ..." --sender BOC', ""),
        ("3 · Singlish: 'my account was hacked, send me the OTP you got'",
         ["check", "Machan mage account eka hack una. Oyata awa OTP eka mata ewanna please"],
         'check "Machan mage account eka hack una. Oyata awa OTP eka mata ewanna please"',
         "The reply is written in Sinhala script; this recording machine has no Sinhala font, so its English text is shown."),
        ("4 · Family impersonation: not sure, so it goes to a human",
         ["check", "Hi amma this is my new number. Phone broke. Please send 25000 by ez cash to 0712345678 urgently"],
         'check "Hi amma this is my new number. Phone broke. Please send 25000 by ez cash ..."', ""),
    ]
    for caption, args, shown_cmd, note in demos:
        out = run(args)
        if "Reply (sinhala):" in out:   # replace unrenderable Sinhala lines with the English template text
            head = out.split("Reply (sinhala):")[0]
            tail = out.split("Rakshaka never asks for your OTP, PIN or NIC.")[-1] if "Rakshaka never" in out else ""
            sys.path.insert(0, str(ROOT / "project"))
            from rakshaka_agents.decision import ExplainerAgent
            verdict = "SCAM" if "Verdict : SCAM" in out else "UNCERTAIN" if "UNCERTAIN" in out else "LIKELY_SAFE"
            keys = [e.split(":")[1] for e in out.split("explainer")[1].splitlines()[0].split() if e.startswith("reason:")]
            english = ExplainerAgent().template_reply(verdict, keys, "english")
            out = head + "Reply (sinhala, English text shown):\n" + english + "\n" + "\n".join(
                l for l in out.strip().splitlines()[-1:])
        terminal(caption, "python project/main.py " + shown_cmd, out, 9, note)

    review = run(["review"])
    terminal("5 · Human in the loop: the review queue", "python project/main.py review", review, 7)
    item = next((l.split("]")[0].strip("[ ") for l in review.splitlines() if l.startswith("[")), None)
    if item:
        labelled = run(["label", item, "scam"])
        terminal("5 · The reviewer labels it; the label feeds gated retraining", f"python project/main.py label {item} scam",
                 labelled, 6)

    bench = json.loads((ROOT / "project" / "reports" / "benchmark.json").read_text(encoding="utf-8"))
    d = bench["datasets"]
    pct = lambda x: f"{100 * x:.1f}%"
    slide("Multi-agent vs single agent", [
        f"New tactics: {pct(d['shifted']['multi_agent']['scam_caught'])} vs {pct(d['shifted']['single_agent']['scam_caught'])} of scams caught · "
        f"stress set: {pct(d['stress']['multi_agent']['scam_caught'])} vs {pct(d['stress']['single_agent']['scam_caught'])} · 0% false alarms",
        f"~Same data, model and thresholds for both. Cost: ~{d['test']['multi_agent']['latency_p50_ms']:.0f} ms vs "
        f"~{d['test']['single_agent']['latency_p50_ms']:.0f} ms per message. Stress set written alongside the link rules (biased).",
    ], 16, image=ROOT / "docs" / "figures" / "benchmark_scam_caught.png", kicker="Benchmark (python project/main.py benchmark)")

    human = ROOT / "project" / "reports" / "human_baseline" / "results.json"
    if human.exists():
        h = json.loads(human.read_text(encoding="utf-8"))
        hs, m = h["systems"]["humans_pooled"], h["systems"]["multi_agent"]
        slide("Human baseline (in progress)", [
            f"Raters so far: {h['n_raters']} (collection continues until 29 Nov)",
            f"Human: {pct(hs['scam_caught'])} of scams caught, {pct(hs['unsafe_miss'])} called safe, {hs['seconds_per_message']} s per message",
            f"Multi-agent on the same 40 messages: {pct(m['scam_caught'])} caught, {pct(m['unsafe_miss'])} called safe",
            "", "~Too few raters for a conclusion yet; reported as collected, nothing estimated."], 12, kicker="Rule 04")

    slide("Honest limitations and next steps", [
        "• All data is synthetic or hand-written: the design works; real-world accuracy is not claimed",
        "• Known misses: one Tanglish gift-card scam, some unusual Singlish (documented)",
        "• Sinhala and Tamil replies need native-speaker review",
        "• By 29 Nov: more human raters, review desk UI, process workers, full demo video",
    ], 14, kicker="What is not done")
    slide("Thank you", ["github.com/geemalfernando/byte_benders-uom", "",
                        "~Geemal Fernando · Thisuka Mahiru · Chanith Wijekoon · Pamindu Piumaka"], 6, kicker="Byte Benders")
    shutil.rmtree(runtime, ignore_errors=True)        # do not leave demo labels behind

    tmp = Path(tempfile.mkdtemp())
    lines = []
    for i, (im, secs) in enumerate(frames):
        p = tmp / f"{i:04d}.png"
        im.save(p)
        lines += [f"file '{p}'", f"duration {secs}"]
    lines.append(f"file '{tmp / f'{len(frames) - 1:04d}.png'}'")
    (tmp / "list.txt").write_text("\n".join(lines))
    out = ROOT / "project-demo.mp4"
    subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-f", "concat", "-safe", "0", "-i", str(tmp / "list.txt"),
                    "-f", "lavfi", "-i", "anullsrc=channel_layout=stereo:sample_rate=44100",
                    "-vf", "fps=25,format=yuv420p", "-c:v", "libx264", "-preset", "veryfast", "-crf", "20",
                    "-c:a", "aac", "-b:a", "96k", "-shortest", "-movflags", "+faststart", str(out)], check=True)
    shutil.rmtree(tmp)
    return out


if __name__ == "__main__":
    print(main())
